INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 20, 'theory', 'Quiz: containers, calls and with');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 0, 'Which error should a sequence''s __getitem__ raise when the index doesn''t exist?', '["KeyError", "IndexError", "ValueError", "StopIteration"]', 1, 'IndexError tells Python the sequence has ended; iteration without __iter__ relies on exactly that.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 1, 'What does __getitem__ receive when you write items[1:3]?', '["The tuple (1, 3)", "The list [1, 2]", "The object slice(1, 3, None)", "Two arguments: 1 and 3"]', 2, 'A slice arrives as a single key, a slice object; its indices(len) method gives ready-made bounds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 2, 'Why is inheriting from dict and overriding __setitem__ unreliable?', '["dict forbids inheritance", "Built-in methods such as update don''t call your __setitem__", "__setitem__ cannot be overridden", "The class becomes unhashable"]', 1, 'dict is written in C and updates its table directly; for overrides use UserDict or Mapping.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 3, 'What happens if __exit__ returns True?', '["The exit is repeated", "The exception from the with block is suppressed", "The object is closed twice", "The exception propagates further"]', 1, 'A true value from __exit__ says the error has been handled; otherwise the exception continues on its way.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 20, 4, 'What will callable(Multiplier(3)) print if Multiplier has __call__?', '["False", "None", "An error", "True"]', 3, 'An instance with __call__ can be called like a function, and callable() checks exactly that.');
